// Adaptive HEVC — Source Profile (flow 1, after the HEVC/AV1 checks).
// Assesses the original before anything is encoded:
//   - codec family + efficiency, resolution, frame rate, bit depth
//   - quality as bits-per-pixel (bpp), normalised to H.264-equivalent by codec efficiency
//   - HDR10 / HLG / Dolby Vision
//   - conform needs: deinterlace (field_order, else idet on SD/legacy codecs), regenerate timestamps
//     (AVI / MPEG-PS / TS), even dimensions, audio MKV can't hold (-> FLAC), subtitles to drop
// Output 1 = encode candidate (variables set), 2 = skip (keep original; reason logged)
const { execFile } = require('child_process');

// How efficient each source codec is relative to H.264 (higher = more efficient). Used to scale
// both the "is it already lean?" test and the size targets: MPEG-2 at 25% of its size is about as
// "far" as H.264 at 50%.
const EFFICIENCY = { mpeg1video: 0.45, mpeg2video: 0.5, msmpeg4v2: 0.55, msmpeg4v3: 0.6, mpeg4: 0.65, wmv1: 0.6, wmv2: 0.65,
  wmv3: 0.8, vc1: 0.85, vp8: 0.9, h264: 1.0, vp9: 1.4 };
const LEAN_BPP = 0.045;   // H.264-equivalent bits/pixel below which a source is already lean (≈2.5 Mbps 1080p24)
const LEGACY = ['mpeg1video', 'mpeg2video', 'mpeg4', 'msmpeg4v2', 'msmpeg4v3', 'wmv1', 'wmv2', 'wmv3', 'vc1'];
const MKV_PCM_OK = ['pcm_s16le', 'pcm_s24le', 'pcm_s32le', 'pcm_f32le', 'pcm_s16be', 'pcm_u8'];

function run(bin, argv) {
  return new Promise((resolve, reject) => execFile(bin, argv, { maxBuffer: 64 * 1024 * 1024 },
    (e, out, err) => (e ? reject(Object.assign(e, { stderr: String(err) })) : resolve({ stdout: String(out), stderr: String(err) }))));
}
const num = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : 0; };
const fps = (r) => { const [a, b] = String(r || '0/1').split('/').map(Number); return b ? a / b : 0; };

module.exports = async (args) => {
  const user = (args.variables.user = args.variables.user || {});
  const log = (m) => args.jobLog(`[source profile] ${m}`);
  const ffprobe = args.ffProbePath || 'tdarr-ffprobe';
  const ffmpeg = args.ffmpegPath || 'tdarr-ffmpeg';
  const file = args.inputFileObj._id;
  const skip = (why) => { user.report_decision = `skip: ${why}`; log(`SKIP - ${why}`); return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables }; };

  const info = JSON.parse((await run(ffprobe, ['-v', 'error', '-print_format', 'json', '-show_format', '-show_streams', file])).stdout);
  const streams = info.streams || [];
  const v = streams.find((s) => s.codec_type === 'video' && !(s.disposition && Number(s.disposition.attached_pic) === 1));
  if (!v) return skip('no video stream');
  const codec = v.codec_name;
  if (['hevc', 'av1'].includes(codec)) return skip(`already ${codec}`);
  if ((v.side_data_list || []).some((s) => /DOVI/i.test(s.side_data_type || ''))) return skip('Dolby Vision (re-encoding would drop the DV layer)');

  const container = String(info.format.format_name || '');
  const duration = num(info.format.duration) || num(v.duration);
  const width = num(v.width); const height = num(v.height);
  const rate = fps(v.avg_frame_rate) || fps(v.r_frame_rate) || 24;
  const fileBytes = num(info.format.size);
  // Video bitrate: per-stream tags (MKV "BPS" statistics) can be stale when a tool re-encoded the file
  // but copied the old tags, so cross-check them against the real size/duration and fall back to
  // "total minus the other streams" when they disagree.
  const totalKbps = duration ? (fileBytes * 8 / 1000) / duration : 0;
  const streamKbps = (s) => (num(s.bit_rate) || num(s.tags && (s.tags.BPS || s.tags['BPS-eng']))) / 1000;
  const otherKbps = Math.min(totalKbps * 0.6, streams.filter((s) => s !== v).reduce((a, s) => a + streamKbps(s), 0));
  const sizeKbps = Math.max(0, totalKbps - otherKbps);
  let vKbps = streamKbps(v);
  if (totalKbps && (!vKbps || vKbps > totalKbps * 1.05 || vKbps < sizeKbps * 0.6)) {
    if (vKbps) log(`video bitrate tag ${vKbps.toFixed(0)} kbps disagrees with the file size (~${sizeKbps.toFixed(0)} kbps); using the size-based figure`);
    vKbps = sizeKbps;
  }
  const eff = EFFICIENCY[codec] || 0.8;
  const bpp = width && height && rate && vKbps ? (vKbps * 1000) / (width * height * rate) : 0;
  const effBpp = bpp * eff;
  const quality = !bpp ? 'unknown' : effBpp >= 0.25 ? 'high (remux/disc-like)' : effBpp >= 0.08 ? 'standard' : effBpp >= LEAN_BPP ? 'lean' : 'very lean';
  const transfer = v.color_transfer || '';
  const hdr = transfer === 'smpte2084' ? 'HDR10' : transfer === 'arib-std-b67' ? 'HLG' : 'SDR';
  log(`${codec} (${v.profile || '?'}, ${v.pix_fmt || '?'}) ${width}x${height} @ ${rate.toFixed(3)} fps in ${container}, ${(duration / 60).toFixed(1)} min`);
  log(`video ${vKbps.toFixed(0)} kbps = ${bpp.toFixed(3)} bpp (x${eff} efficiency = ${effBpp.toFixed(3)} H.264-equiv) -> quality: ${quality} | ${hdr}`);
  if (duration < 20) return skip('shorter than 20 s');
  if (bpp && effBpp < LEAN_BPP) return skip(`already lean (${effBpp.toFixed(3)} H.264-equiv bpp < ${LEAN_BPP}); re-encoding would mostly cost quality`);

  // ── conform needs ─────────────────────────────────────────────────────────
  const filters = [];
  let interlaced = ['tt', 'bb', 'tb', 'bt'].includes(v.field_order);
  let how = `field_order=${v.field_order || 'unset'}`;
  if (!interlaced && (LEGACY.includes(codec) || height <= 576) && duration > 60) {
    try {   // idet over ~600 frames from a quarter of the way in
      const { stderr } = await run(ffmpeg, ['-hide_banner', '-nostats', '-ss', String(Math.floor(duration * 0.25)), '-i', file,
        '-map', '0:v:0', '-frames:v', '600', '-vf', 'idet', '-an', '-sn', '-f', 'null', '-']);
      const m = stderr.match(/Multi frame detection: TFF:\s*(\d+) BFF:\s*(\d+) Progressive:\s*(\d+)/);
      if (m) {
        const [tff, bff, prog] = m.slice(1).map(Number);
        interlaced = (tff + bff) > 0.3 * (tff + bff + prog);
        how = `idet TFF ${tff} / BFF ${bff} / progressive ${prog}`;
      }
    } catch (e) { how += ' (idet failed)'; }
  }
  if (interlaced) filters.push('bwdif=mode=send_frame:parity=auto:deint=all');
  if (width % 2 || height % 2) filters.push('crop=trunc(iw/2)*2:trunc(ih/2)*2');
  const genpts = /avi|mpeg|mpegts|vob|asf/.test(container);
  const audioFlac = streams.filter((s) => s.codec_type === 'audio' && /^pcm_/.test(s.codec_name) && !MKV_PCM_OK.includes(s.codec_name)).map((s) => s.index);

  user.src_codec = codec;
  user.src_efficiency = String(eff);
  user.src_kbps = String(Math.round(vKbps));
  user.src_bpp = bpp.toFixed(4);
  user.src_height = String(height);
  user.src_bytes = String(fileBytes);
  user.src_video_bytes = String(Math.round((vKbps * 1000 / 8) * duration) || Math.round(fileBytes * 0.85));
  user.src_duration = String(duration);
  user.src_audio_count = String(streams.filter((s) => s.codec_type === 'audio').length);
  user.is_hdr = hdr === 'SDR' ? 'false' : 'true';
  user.hdr_type = hdr;
  user.conform_filter = filters.join(',');
  user.conform_genpts = genpts ? 'true' : 'false';
  user.conform_audio_flac = audioFlac.join(',');
  log(`conform: interlaced=${interlaced} (${how}) | filters: ${user.conform_filter || 'none'} | regenerate timestamps: ${genpts} | audio->FLAC: ${user.conform_audio_flac || 'none'}`);
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Adaptive HEVC — Quality Report (flow 1, after Source Profile and the CPU/GPU choice).
// Finds the encoder quality value (x265 CRF, or NVENC CQ) for THIS file by test-encoding samples:
//   1. cut 3 short samples spread through the file (stream copy)
//   2. encode them with the real settings (encoder, preset, 10-bit, conform filters)
//   3. measure size vs the source samples and SSIM (vs the source run through the same filters)
//   4. search toward the target size (log-size model, refit from measurements), never below the
//      SSIM floor and never shrinking further than the minimum; skip if not worth encoding
// Size rules are for the WHOLE FILE, the same for every source type: aim for 50% of the original,
// never below 40%, skip if it can't get under 80%. Audio/subtitles are copied, so each file's rule is
// converted to a video-stream target from how much of the file is video.
// Output 1 = encode (encode_quality etc. set), 2 = skip (keep original; reason logged)
const { execFile } = require('child_process');
const fs = require('fs');
const path = require('path');

const DEFAULTS = { fileTarget: 0.50, fileMin: 0.40, fileMax: 0.80, ssimFloor: 0.975, maxRounds: 5 };
const ENCODERS = {
  libx265: { label: 'x265 CRF', lo: 16, hi: 34, ref28Kbps: 2300 },
  hevc_nvenc: { label: 'NVENC CQ', lo: 18, hi: 38, ref28Kbps: 2900 },   // NVENC needs ~1-2 more CQ for the same size
};

function run(bin, argv) {
  return new Promise((resolve, reject) => execFile(bin, argv, { maxBuffer: 64 * 1024 * 1024 },
    (e, out, err) => (e ? reject(Object.assign(e, { stderr: String(err).slice(-2000) })) : resolve({ stdout: String(out), stderr: String(err) }))));
}
const num = (v) => { const n = parseFloat(v); return Number.isFinite(n) ? n : 0; };
function userVar(args, name, dflt) {
  const lib = (args.userVariables && args.userVariables.library) || {};
  const glob = (args.userVariables && args.userVariables.global) || {};
  const val = lib[name] !== undefined && lib[name] !== '' ? lib[name] : glob[name];
  const n = parseFloat(val);
  return Number.isFinite(n) ? n : dflt;
}

async function firstFrameSideData(ffprobe, file) {
  try {
    const { stdout } = await run(ffprobe, ['-v', 'error', '-select_streams', 'v:0', '-print_format', 'json',
      '-show_frames', '-read_intervals', '%+#1', '-show_entries', 'frame=side_data_list', file]);
    const f = (JSON.parse(stdout).frames || [])[0];
    return (f && f.side_data_list) || [];
  } catch (e) { return []; }
}

// x265 HDR10 / HLG parameters so the encode keeps the colour metadata
function hdrParams(v, side) {
  const transfer = v.color_transfer || '';
  if (transfer !== 'smpte2084' && transfer !== 'arib-std-b67') return [];
  const p = [`colorprim=${v.color_primaries || 'bt2020'}`, `transfer=${transfer}`,
    `colormatrix=${v.color_space === 'bt2020c' ? 'bt2020c' : 'bt2020nc'}`, 'repeat-headers=1'];
  if (transfer === 'smpte2084') {
    p.push('hdr10=1', 'hdr10-opt=1');
    const md = side.find((s) => /Mastering display/i.test(s.side_data_type || ''));
    const cl = side.find((s) => /Content light/i.test(s.side_data_type || ''));
    const r = (x) => { const [a, b] = String(x || '0/1').split('/').map(Number); return b ? a / b : 0; };
    if (md && md.red_x) {
      const c = (x) => Math.round(r(x) * 50000); const l = (x) => Math.round(r(x) * 10000);
      p.push(`master-display=G(${c(md.green_x)},${c(md.green_y)})B(${c(md.blue_x)},${c(md.blue_y)})R(${c(md.red_x)},${c(md.red_y)})WP(${c(md.white_point_x)},${c(md.white_point_y)})L(${l(md.max_luminance)},${l(md.min_luminance)})`);
    }
    if (cl) p.push(`max-cll=${cl.max_content || 0},${cl.max_average || 0}`);
  }
  return p;
}

// The encoder arguments used for BOTH the samples and the real encode (build_encode.js mirrors this)
function videoArgs(encoder, q, x265Params, vKbps) {
  if (encoder === 'hevc_nvenc') {
    const a = ['-c:v', 'hevc_nvenc', '-preset', 'p7', '-tune', 'hq', '-rc', 'vbr', '-cq', String(q), '-b:v', '0',
      '-profile:v', 'main10', '-pix_fmt', 'p010le'];
    if (vKbps) a.push('-maxrate', `${Math.round(vKbps)}k`, '-bufsize', `${Math.round(vKbps * 2)}k`);
    return a;
  }
  return ['-c:v', 'libx265', '-preset', 'slow', '-crf', String(q), '-pix_fmt', 'yuv420p10le', '-profile:v', 'main10',
    '-x265-params', ['log-level=error', ...x265Params].join(':')];
}

module.exports = async (args) => {
  const user = (args.variables.user = args.variables.user || {});
  const log = (m) => args.jobLog(`[quality report] ${m}`);
  const ffmpeg = args.ffmpegPath || 'tdarr-ffmpeg';
  const ffprobe = args.ffProbePath || 'tdarr-ffprobe';
  const file = args.inputFileObj._id;
  const skip = (why) => { user.report_decision = `skip: ${why}`; log(`SKIP - ${why}`); return { outputFileObj: args.inputFileObj, outputNumber: 2, variables: args.variables }; };
  if (!user.src_codec) throw new Error('Source Profile has not run (src_codec unset)');

  // encoder: chosen by the CPU/GPU branch; HDR always goes to x265 so its metadata survives
  let encoder = user.encoder === 'hevc_nvenc' ? 'hevc_nvenc' : 'libx265';
  if (encoder === 'hevc_nvenc' && user.is_hdr === 'true') { encoder = 'libx265'; log(`${user.hdr_type} source: using CPU x265 instead of NVENC to keep HDR metadata`); }
  user.encoder = encoder;
  const enc = ENCODERS[encoder];

  // whole-file rules -> video-stream targets (non-video bytes are copied unchanged)
  const fileTarget = userVar(args, 'v8_target_ratio', DEFAULTS.fileTarget);
  const fileMin = userVar(args, 'v8_min_ratio', DEFAULTS.fileMin);
  const fileMax = userVar(args, 'v8_max_ratio', DEFAULTS.fileMax);
  const fileBytes = num(user.src_bytes); const vBytes = num(user.src_video_bytes) || fileBytes * 0.85;
  const other = fileBytes ? Math.max(0, Math.min(0.9, (fileBytes - vBytes) / fileBytes)) : 0.15;   // share of file that isn't video
  const toVideo = (f) => (f - other) / (1 - other);
  const toFile = (r) => other + (1 - other) * r;
  const cfg = {
    ...DEFAULTS,
    targetRatio: Math.max(0.15, toVideo(fileTarget)),
    minRatio: Math.max(0.10, toVideo(fileMin)),
    ssimFloor: userVar(args, 'v8_ssim_floor', DEFAULTS.ssimFloor),
  };
  const vKbps = num(user.src_kbps);
  const height = num(user.src_height) || 1080;
  const duration = num(user.src_duration);

  const info = JSON.parse((await run(ffprobe, ['-v', 'error', '-print_format', 'json', '-show_streams', '-select_streams', 'v:0', file])).stdout);
  const v = (info.streams || [])[0] || {};
  const x265Params = encoder === 'libx265' ? hdrParams(v, await firstFrameSideData(ffprobe, file)) : [];
  if (encoder === 'libx265' && vKbps) x265Params.push(`vbv-maxrate=${Math.round(vKbps)}`, `vbv-bufsize=${Math.round(vKbps * 2)}`);   // never above source bitrate
  const filter = user.conform_filter || '';
  const genpts = user.conform_genpts === 'true' ? ['-fflags', '+genpts'] : [];

  const ref = enc.ref28Kbps * Math.pow((height / 1080) ** 2, 0.75);
  const guess = vKbps ? 28 + 6 * Math.log2(ref / (vKbps * cfg.targetRatio)) : (enc.lo + enc.hi) / 2;
  const clampQ = (q) => Math.max(enc.lo, Math.min(enc.hi, Math.round(q)));
  log(`${enc.label} search: whole file target ${(fileTarget * 100).toFixed(0)}% (min ${(fileMin * 100).toFixed(0)}%, skip above ${(fileMax * 100).toFixed(0)}%) = video ${(cfg.targetRatio * 100).toFixed(0)}% (min ${(cfg.minRatio * 100).toFixed(0)}%; ${(other * 100).toFixed(0)}% of the file is audio/subs), SSIM floor ${cfg.ssimFloor}, first guess ${clampQ(guess)}${filter ? `, filters ${filter}` : ''}`);

  // ── samples ───────────────────────────────────────────────────────────────
  const work = path.join(args.workDir, 'quality-report');
  fs.mkdirSync(work, { recursive: true });
  const n = duration < 180 ? 1 : 3;
  const len = Math.min(duration < 180 ? duration * 0.5 : (height > 1600 ? 6 : 8), 30);
  const src = [];
  for (let i = 0; i < n; i += 1) {
    const at = n === 1 ? duration * 0.1 : duration * (0.15 + (0.7 * i) / (n - 1));
    const out = path.join(work, `src${i}.mkv`);
    await run(ffmpeg, ['-hide_banner', '-loglevel', 'error', '-y', ...genpts, '-ss', at.toFixed(2), '-i', file, '-t', len.toFixed(2),
      '-map', '0:v:0', '-c', 'copy', '-an', '-sn', out]);
    src.push(out);
  }
  const srcBytes = src.reduce((a, f) => a + fs.statSync(f).size, 0);

  // ── search ────────────────────────────────────────────────────────────────
  const tried = [];
  const measure = async (q) => {
    const t0 = Date.now(); let bytes = 0; const ss = [];
    for (let i = 0; i < src.length; i += 1) {
      const out = path.join(work, `enc${i}_q${q}.mkv`);
      await run(ffmpeg, ['-hide_banner', '-loglevel', 'error', '-y', '-i', src[i], '-map', '0:v:0', ...(filter ? ['-vf', filter] : []),
        ...videoArgs(encoder, q, x265Params, vKbps), '-an', '-sn', out]);
      bytes += fs.statSync(out).size;
      const refChain = `${filter ? `${filter},` : ''}format=yuv420p10le`;
      const { stderr } = await run(ffmpeg, ['-hide_banner', '-nostats', '-i', out, '-i', src[i], '-lavfi',
        `[0:v]format=yuv420p10le[a];[1:v]${refChain}[b];[a][b]ssim`, '-f', 'null', '-']);
      const m = stderr.match(/SSIM Y:([0-9.]+)/);
      if (m) ss.push(parseFloat(m[1]));
    }
    const r = { q, ratio: bytes / srcBytes, ssim: ss.length ? ss.reduce((a, b) => a + b, 0) / ss.length : null };
    tried.push(r);
    log(`round ${tried.length}: ${enc.label} ${q} -> video ${(r.ratio * 100).toFixed(1)}% of source, SSIM ${r.ssim === null ? 'n/a' : r.ssim.toFixed(4)} (${((Date.now() - t0) / 1000).toFixed(0)} s)`);
    return r;
  };
  // ── search: bracket the target, then interpolate on the measured size curve ───────────────
  // Size curves differ a lot (lean WEB ~6 CRF per halving; grainy Blu-ray can be ~2-3), so after the
  // first measurement the next guess comes from measured points. A result pinned at the VBV cap (>95%)
  // only says "too big". A CRF that fails the SSIM floor caps every later guess below it.
  const capped = (t) => t.ratio > 0.95;
  const qualityOk = (t) => t.ssim === null || t.ssim >= cfg.ssimFloor;
  const onTarget = (t) => Math.abs(toFile(t.ratio) - fileTarget) <= 0.05 && t.ratio >= cfg.minRatio;
  const bracket = () => ({
    big: tried.filter((t) => t.ratio > cfg.targetRatio).sort((a, b) => b.q - a.q)[0],     // highest q still too big
    small: tried.filter((t) => t.ratio <= cfg.targetRatio).sort((a, b) => a.q - b.q)[0],  // lowest q already small enough
  });
  const between = (big, small, r) => big.q + (small.q - big.q) * Math.log(big.ratio / r) / Math.log(big.ratio / small.ratio);
  const slope = () => {   // quality steps per halving of size: bracket if we have one, else uncapped points, else 6
    const { big, small } = bracket();
    if (big && small && !capped(big) && small.q > big.q) return Math.max(1.5, Math.min(12, (small.q - big.q) / Math.log2(big.ratio / small.ratio)));
    const u = tried.filter((t) => !capped(t));
    if (u.length < 2) return 6;
    const [a, b] = u.slice(-2); const d = Math.log2(a.ratio / b.ratio);
    return Math.abs(d) > 0.05 ? Math.max(1.5, Math.min(12, (b.q - a.q) / d)) : 6;
  };

  let qCeil = enc.hi;
  let cur = await measure(clampQ(guess));
  for (;;) {
    if (!qualityOk(cur)) qCeil = Math.min(qCeil, cur.q - 1);
    if (qualityOk(cur) && onTarget(cur)) break;
    if (tried.length >= cfg.maxRounds) break;
    const { big, small } = bracket();
    let next;
    if (big && small) next = between(big, small, cfg.targetRatio);
    else if (big) next = big.q + Math.max(capped(big) ? 4 : 1, slope() * Math.log2(big.ratio / cfg.targetRatio));
    else next = small.q - Math.max(1, slope() * Math.log2(cfg.targetRatio / small.ratio));
    next = clampQ(next);
    if (big && small) next = Math.max(big.q + 1, Math.min(small.q - 1, next));   // stay inside the bracket
    next = Math.min(next, qCeil);
    if (next < enc.lo) break;                     // quality floor can't be met inside the allowed range
    next = clampQ(next);
    if (tried.some((t) => t.q === next)) break;   // bracket closed: nothing new to learn
    cur = await measure(next);
  }
  fs.rmSync(work, { recursive: true, force: true });

  // choose: closest to target among measured points that pass quality and the minimum
  const valid = tried.filter((t) => qualityOk(t) && t.ratio >= cfg.minRatio);
  let best = valid.length ? valid.reduce((a, b) => (Math.abs(toFile(b.ratio) - fileTarget) < Math.abs(toFile(a.ratio) - fileTarget) ? b : a)) : null;
  let estimated = false;
  const { big, small } = bracket();
  // not converged but the target is bracketed: use the interpolated value; Verify measures the real
  // result and can retry once, which is far better than skipping or taking a distant point
  if ((!best || !onTarget(best)) && big && small && small.q - big.q > 1) {
    const q = Math.min(qCeil, Math.max(big.q + 1, Math.min(small.q - 1, Math.round(between(big, small, cfg.targetRatio)))));
    const t = (q - big.q) / (small.q - big.q);
    best = { q, ratio: Math.exp(Math.log(big.ratio) + t * (Math.log(small.ratio) - Math.log(big.ratio))), ssim: small.ssim };
    estimated = true;
  }
  if (!best) {
    const lowest = tried.reduce((a, b) => (b.q < a.q ? b : a));
    if (lowest.ratio < cfg.minRatio && lowest.q <= enc.lo + 1) return skip(`even ${enc.label} ${enc.lo} shrinks the file to ~${(toFile(lowest.ratio) * 100).toFixed(0)}% (rule: never below ${(fileMin * 100).toFixed(0)}%)`);
    return skip(`no ${enc.label} value met the SSIM floor ${cfg.ssimFloor} at a useful size`);
  }
  const predicted = Math.min(1, toFile(best.ratio));
  if (predicted > fileMax) return skip(`best quality-safe ${enc.label} ${best.q} only gets the file to ~${(predicted * 100).toFixed(0)}% (skip above ${(fileMax * 100).toFixed(0)}%)`);
  if (estimated) log(`not converged in ${tried.length} rounds; target bracketed by ${enc.label} ${big.q} (${(big.ratio * 100).toFixed(0)}%) and ${small.q} (${(small.ratio * 100).toFixed(0)}%) -> interpolated ${best.q}; Verify will confirm`);
  Object.assign(user, {
    encode_quality: String(best.q), encode_attempt: '1', x265_params: x265Params.join(':'),
    report_target: cfg.targetRatio.toFixed(3), report_min: cfg.minRatio.toFixed(3), report_slope: slope().toFixed(2),
    report_file_target: fileTarget.toFixed(3), report_file_min: fileMin.toFixed(3),
    report_q_lo: String(enc.lo), report_q_hi: String(enc.hi),
    report_video_ratio: best.ratio.toFixed(3), report_file_ratio: predicted.toFixed(3),
    report_ssim: best.ssim === null ? '' : best.ssim.toFixed(4), report_decision: 'encode',
  });
  log(`DECISION: ${enc.label} ${best.q}${estimated ? ' (interpolated)' : ''} | video ~${(best.ratio * 100).toFixed(0)}% | whole file ~${(predicted * 100).toFixed(0)}% | SSIM ${user.report_ssim || 'n/a'}${estimated ? ' (nearest measured)' : ''}`);
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Adaptive HEVC — build the single encode command (flow 2, after "Begin FFmpeg Command").
// Everything v7's separate Conform pass did, plus the conform needs found by Source Profile, in one encode:
//   video: libx265 CRF (CPU) or hevc_nvenc CQ (GPU) at the Quality Report's value, 10-bit, same
//          arguments as the report's samples; deinterlace / even-crop filter when needed
//   input: regenerate timestamps for AVI / MPEG-PS / TS sources
//   audio: copy, except PCM variants MKV can't hold -> FLAC
//   subtitles: mov_text/webvtt/text -> SRT, image + SRT/ASS copied, unsupported dropped
//   data streams and cover art dropped, fonts kept | order video, audio, subtitle, attachment | MKV
module.exports = async (args) => {
  const cmd = args.variables.ffmpegCommand;
  const user = args.variables.user || {};
  const log = (m) => args.jobLog(`[build encode] ${m}`);
  const q = user.encode_quality;
  if (!q) throw new Error('encode_quality is not set - the Quality Report (flow 1) did not run');
  const nvenc = user.encoder === 'hevc_nvenc';
  const vKbps = parseFloat(user.src_kbps) || 0;

  const toSrt = ['mov_text', 'webvtt', 'text', 'tx3g'];
  const copySubs = ['subrip', 'srt', 'ass', 'ssa', 'hdmv_pgs_subtitle', 'dvd_subtitle', 'dvb_subtitle', 'xsub'];
  const flacAudio = String(user.conform_audio_flac || '').split(',').filter(Boolean).map(Number);
  const rank = { video: 0, audio: 1, subtitle: 2, attachment: 3 };
  let videoSet = false;
  const notes = [];

  for (const s of cmd.streams) {
    const type = s.codec_type;
    const coverArt = s.disposition && Number(s.disposition.attached_pic) === 1;
    if (type === 'video' && !coverArt && !videoSet) {
      videoSet = true;
      if (user.conform_filter) s.outputArgs.push('-filter:{outputIndex}', user.conform_filter);
      if (nvenc) {
        s.outputArgs.push('-c:{outputIndex}', 'hevc_nvenc', '-preset', 'p7', '-tune', 'hq', '-rc', 'vbr', '-cq', q, '-b:v', '0',
          '-profile:{outputIndex}', 'main10', '-pix_fmt:{outputIndex}', 'p010le');
        if (vKbps) s.outputArgs.push('-maxrate', `${Math.round(vKbps)}k`, '-bufsize', `${Math.round(vKbps * 2)}k`);
      } else {
        s.outputArgs.push('-c:{outputIndex}', 'libx265', '-crf', q, '-preset', 'slow',
          '-profile:{outputIndex}', 'main10', '-pix_fmt:{outputIndex}', 'yuv420p10le');
        if (user.x265_params) s.outputArgs.push('-x265-params', user.x265_params);
      }
    } else if (coverArt || type === 'data') {
      s.removed = true; notes.push(`drop #${s.index} ${coverArt ? 'cover art' : 'data'} (${s.codec_name || '?'})`);
    } else if (type === 'audio' && flacAudio.includes(s.index)) {
      s.outputArgs.push('-c:{outputIndex}', 'flac'); notes.push(`audio #${s.index} ${s.codec_name} -> flac`);
    } else if (type === 'subtitle') {
      if (toSrt.includes(s.codec_name)) { s.outputArgs.push('-c:{outputIndex}', 'srt'); notes.push(`sub #${s.index} ${s.codec_name} -> srt`); }
      else if (!copySubs.includes(s.codec_name)) { s.removed = true; notes.push(`drop #${s.index} subtitle ${s.codec_name || 'unknown'} (not muxable to MKV)`); }
    }
  }
  if (!videoSet) throw new Error('no video stream to encode');

  if (user.conform_genpts === 'true') cmd.overallInputArguments.push('-fflags', '+genpts');
  cmd.streams.sort((a, b) => (rank[a.codec_type] ?? 9) - (rank[b.codec_type] ?? 9));
  cmd.container = 'mkv';
  cmd.shouldProcess = true;
  cmd.overallOuputArguments.push('-max_muxing_queue_size', '9999');
  log(`attempt ${user.encode_attempt || 1}: ${nvenc ? `NVENC CQ ${q}` : `x265 CRF ${q} slow`}, 10-bit${user.conform_filter ? `, filter ${user.conform_filter}` : ''}${user.conform_genpts === 'true' ? ', regenerate timestamps' : ''}`);
  if (notes.length) log(notes.join('; '));
  return { outputFileObj: args.inputFileObj, outputNumber: 1, variables: args.variables };
};

// Adaptive HEVC — verify the encode before anything replaces the original (flow 3).
// Output 1 = good -> replace + notify
// Output 2 = keep original (broken encode, or still out of range after the allowed retries)
// Output 3 = retry: re-encode once more with a corrected quality value (counter: encode_attempt,
//            limit: v8_max_retries, default 1). The correction uses the REAL full-file result, so a
//            single retry is normally enough.
const { execFile } = require('child_process');
const fs = require('fs');

// Whole-file window (target 50%, never below 40%): retry outside 37-70%; after the retries a file
// between 70% and 85% is still accepted (it saved space), anything else keeps the original.
const RETRY_ABOVE = 0.70;      // further from the 50% target than the samples should ever miss by
const ACCEPT_UP_TO = 0.85;     // after retries: still worth replacing if it saves 15%+
const GRACE = 0.03;            // sample-based estimates: allow 37% before calling it "below 40%"
const BROKEN_BELOW = 0.10;     // smaller than this is a broken encode, not "too good"

function probe(ffprobe, file) {
  return new Promise((resolve, reject) => execFile(ffprobe, ['-v', 'error', '-print_format', 'json', '-show_format', '-show_streams', file],
    { maxBuffer: 32 * 1024 * 1024 }, (e, out) => (e ? reject(e) : resolve(JSON.parse(String(out))))));
}
function userVar(args, name, dflt) {
  const lib = (args.userVariables && args.userVariables.library) || {};
  const glob = (args.userVariables && args.userVariables.global) || {};
  const n = parseFloat(lib[name] !== undefined && lib[name] !== '' ? lib[name] : glob[name]);
  return Number.isFinite(n) ? n : dflt;
}

module.exports = async (args) => {
  const user = args.variables.user || {};
  const log = (m) => args.jobLog(`[verify] ${m}`);
  const ffprobe = args.ffProbePath || 'tdarr-ffprobe';
  const result = (n) => ({ outputFileObj: args.inputFileObj, outputNumber: n, variables: args.variables });
  const keep = (why) => { log(`KEEP ORIGINAL - ${why}`); return result(2); };

  const out = args.inputFileObj._id;
  const outBytes = fs.statSync(out).size;
  const srcBytes = parseFloat(user.src_bytes) || 0;
  const srcVideo = parseFloat(user.src_video_bytes) || srcBytes * 0.85;
  const info = await probe(ffprobe, out);
  const v = (info.streams || []).find((s) => s.codec_type === 'video');
  const audio = (info.streams || []).filter((s) => s.codec_type === 'audio').length;
  const dur = parseFloat(info.format.duration) || 0;
  const srcDur = parseFloat(user.src_duration) || 0;

  // integrity: never retried, the problem isn't the quality value
  if (!v || v.codec_name !== 'hevc') return keep(`output video is ${v ? v.codec_name : 'missing'}, expected hevc`);
  if (srcDur && Math.abs(dur - srcDur) > Math.max(2, srcDur * 0.005)) return keep(`duration ${dur.toFixed(1)} s vs source ${srcDur.toFixed(1)} s (truncated encode?)`);
  if (user.src_audio_count && audio !== parseInt(user.src_audio_count, 10)) return keep(`${audio} audio tracks vs ${user.src_audio_count} in source`);
  if (!srcBytes) return keep('source size unknown');

  const fileRatio = outBytes / srcBytes;
  const videoRatio = Math.max(0.001, (outBytes - (srcBytes - srcVideo)) / srcVideo);   // audio/subs are copied
  const target = parseFloat(user.report_target) || 0.5;   // video-stream target (for the correction maths)
  const fileMin = parseFloat(user.report_file_min) || 0.40;
  const attempt = parseInt(user.encode_attempt || '1', 10);
  const maxRetries = userVar(args, 'v8_max_retries', 1);
  const q = parseInt(user.encode_quality, 10);
  log(`attempt ${attempt}: file ${(fileRatio * 100).toFixed(1)}% of original (report predicted ~${(parseFloat(user.report_file_ratio || 0) * 100).toFixed(0)}%, target ${(parseFloat(user.report_file_target || 0.5) * 100).toFixed(0)}%, min ${(fileMin * 100).toFixed(0)}%) at ${user.encoder === 'hevc_nvenc' ? 'CQ' : 'CRF'} ${q}`);

  if (fileRatio < BROKEN_BELOW) return keep(`output is suspiciously small (${(fileRatio * 100).toFixed(1)}%)`);
  const tooFar = fileRatio < fileMin - GRACE;
  const tooBig = fileRatio > RETRY_ABOVE;
  if (!tooBig && !tooFar) { user.result_file_ratio = fileRatio.toFixed(3); log('OK'); return result(1); }

  const why = tooBig ? `file is ${(fileRatio * 100).toFixed(1)}%, well above the 50% target` : `shrank too far (${(fileRatio * 100).toFixed(1)}% < ${(fileMin * 100).toFixed(0)}% minimum)`;
  if (attempt > maxRetries) {
    if (tooBig && fileRatio <= ACCEPT_UP_TO) { user.result_file_ratio = fileRatio.toFixed(3); log(`ACCEPT - ${why}, but retries are used up and it still saves ${((1 - fileRatio) * 100).toFixed(0)}%`); return result(1); }
    return keep(`${why}; ${attempt - 1} retr${attempt - 1 === 1 ? 'y' : 'ies'} used (limit ${maxRetries})`);
  }

  // corrected quality from the real result: ~slope steps per halving of size
  const slope = parseFloat(user.report_slope) || 6;
  const lo = parseInt(user.report_q_lo || '16', 10); const hi = parseInt(user.report_q_hi || '34', 10);
  let next = Math.round(q + slope * Math.log2(videoRatio / target));
  if (next === q) next = tooBig ? q + 1 : q - 1;
  next = Math.max(lo, Math.min(hi, next));
  if (next === q) return keep(`${why}; quality value already at its limit (${q})`);
  user.encode_quality = String(next);
  user.encode_attempt = String(attempt + 1);
  log(`RETRY ${attempt}/${maxRetries} - ${why}; ${q} -> ${next}`);
  return result(3);
};
